let data = msg.payload;

// Convert JSON string into an object if necessary
if (typeof data === "string") {
    data = JSON.parse(data);
}

// Handle nested payload if present
if (data && data.payload) {
    data = data.payload;
}

// Show the actual incoming structure
node.warn("Received keys: " + Object.keys(data || {}).join(", "));

if (!data || data.raw_value === undefined) {
    node.error("raw_value is missing from incoming data", msg);
    return null;
}

msg.measurement = "sensor_data";

msg.payload = {
    raw_value: Number(data.raw_value),
    moving_average: Number(data.moving_average),
    body_temperature: Number(data.body_temperature),
    fever_flag: Number(data.fever_flag),
    room_temperature: Number(data.room_temperature),
    pressure: Number(data.pressure),
    altitude: Number(data.altitude),
    risk_level: String(data.risk_level)
};

return msg;
